/**
 * How a hero's public win rate changes with the length of the game, at the
 * player's own rank (data/hero-timing.json from STRATZ, regenerated by
 * scripts/coach-hero-timing.mjs). Pure lookups: the engine never fetches.
 *
 * Three groups of game length: under 35 minutes, 35 to 45, 45 or more.
 * Every number carries its sample and its source, and the STRATZ credit
 * travels with it (TIMING_SOURCE.attribution). The same rule as the other
 * baselines: no claim on noise.
 * - A group with fewer than GROUP_MIN games has no win rate (null).
 * - A hero "wins more in shorter games" (or longer) only when the win rate
 *   under 35 minutes and the one at 45 or more are at least LEAN_MIN_GAP
 *   apart and two standard errors of that difference; else "neither" — which
 *   is no claim either way, not "the same in both". Too few games is null,
 *   never "neither".
 *
 * This is each hero alone. Five of them are not a line-up: how they work
 * together and against the other five is not in these numbers.
 */
import { createRequire } from 'node:module';

const R = createRequire(import.meta.url)('./data/hero-timing.json');

export const TIMING_SOURCE = Object.freeze({
  source: R.source, attribution: R.attribution, patch: R.patch, weeks: R.weeks, fetched: R.fetched, games: R.games, cuts: R.cuts,
});
/** The three groups, shortest games first, as the minutes that bound them. */
export const TIMING_GROUPS = Object.freeze(['under_35_min', 'from_35_to_45_min', 'over_45_min']);

const GROUP_MIN = 300;
const LEAN_MIN_GAP = 0.03;
const r3 = (n) => Math.round(n * 1000) / 1000;

/** Which group a game of `seconds` belongs to, by the snapshot's own cuts. Null when the length is unknown. */
export function timingGroupOf(seconds) {
  if (!Number.isFinite(seconds) || seconds <= 0) return null;
  const minutes = seconds / 60;
  return minutes < R.cuts[0] ? TIMING_GROUPS[0] : minutes < R.cuts[1] ? TIMING_GROUPS[1] : TIMING_GROUPS[2];
}

/**
 * [[games, wins] × 3] for hero h in bracket b; with b null, the four brackets summed. Null when the hero is not in the data.
 * @param {number | string} h
 * @param {string | null} b
 * @returns {number[][] | null}
 */
function rowsOf(h, b) {
  if (b != null) return R.heroes?.[b]?.[h] ?? null;
  let sum = null;
  for (const k of Object.keys(R.heroes ?? {})) {
    const row = R.heroes[k]?.[h];
    if (!row) continue;
    sum = sum ? sum.map(([g, w], i) => [g + row[i][0], w + row[i][1]]) : row.map(([g, w]) => [g, w]);
  }
  return sum;
}

/**
 * Hero h's win rate by game length in bracket b (null = all four brackets).
 * @param {number | string} h  hero id
 * @param {string | null} [b]  bracket key (hg, ca, la, di)
 * @returns {null | { games: number, win_rate: number, by_length: Record<string, { games: number, win_rate: number | null }>, wins_more_in: 'shorter_games' | 'longer_games' | 'neither' | null, short_to_long: number | null }}
 *   `short_to_long`: win rate at 45 minutes or more minus the one under 35, in points of win rate (0.031 = 3.1 points); null with too few games in either.
 */
export function heroTiming(h, b = null) {
  return timingFromRows(rowsOf(h, b));
}

/**
 * The same, from the three [games, wins] rows themselves (shortest games first).
 * @param {number[][] | null} rows
 */
export function timingFromRows(rows) {
  if (!Array.isArray(rows) || rows.length !== TIMING_GROUPS.length) return null;
  const games = rows.reduce((a, [g]) => a + g, 0);
  if (!games) return null;
  const wins = rows.reduce((a, [, w]) => a + w, 0);
  const rate = ([g, w]) => (g >= GROUP_MIN ? w / g : null);
  const [short, , long] = rows;
  const p1 = rate(short); const p2 = rate(long);
  let lean = null; let change = null;
  if (p1 != null && p2 != null) {
    change = p2 - p1;
    const se = Math.sqrt((p1 * (1 - p1)) / short[0] + (p2 * (1 - p2)) / long[0]);
    lean = Math.abs(change) >= LEAN_MIN_GAP && Math.abs(change) >= 2 * se ? (change < 0 ? 'shorter_games' : 'longer_games') : 'neither';
  }
  return {
    games, win_rate: r3(wins / games),
    by_length: Object.fromEntries(TIMING_GROUPS.map((k, i) => [k, { games: rows[i][0], win_rate: rate(rows[i]) == null ? null : r3(rate(rows[i])) }])),
    wins_more_in: lean, short_to_long: change == null ? null : r3(change),
  };
}
